	("#6d657b", "#ead8cc"), ("#59706c", "#e8d8c9"), ("#86685a", "#e9dbcc"),
	("#5e7181", "#e7d8cb"), ("#7b6658", "#e7d6c7"), ("#627263", "#eadbcb"),
	("#756b7d", "#e8d8cc"), ("#70704e", "#e7d7c8"),
