def build_portrait_svg(index: int) -> bytes:
	background, clothing = PORTRAIT_PALETTES[index]
	hair = "#292722" if index % 3 else "#5c4538"
	portrait = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 600" role="img" aria-label="Temsili çizim portre">
<rect width="480" height="600" fill="{background}"/>
<path d="M0 468 Q90 390 180 430 T360 420 T480 440 V600 H0Z" fill="#ffffff" opacity=".14"/>
<ellipse cx="240" cy="578" rx="172" ry="34" fill="#24251f" opacity=".12"/>
<path d="M92 570 Q106 430 185 405 L240 445 295 405 Q374 430 388 570Z" fill="{clothing}"/>
<path d="M181 404 L240 456 299 404 276 375 H204Z" fill="#f2eee6"/>
<path d="M166 233 Q165 117 240 110 Q315 117 314 233 L302 326 Q286 390 240 396 Q194 390 178 326Z" fill="#c98f70"/>
<path d="M165 235 Q143 111 240 83 Q339 111 315 244 L299 193 Q270 175 251 145 Q222 184 177 194Z" fill="{hair}"/>
<path d="M183 267 Q199 258 214 267 M266 267 Q281 258 297 267" fill="none" stroke="#342a25" stroke-width="8" stroke-linecap="round"/>
<path d="M224 332 Q240 340 256 332" fill="none" stroke="#8d5149" stroke-width="6" stroke-linecap="round"/>
<path d="M240 275 L230 312 245 314" fill="none" stroke="#a96e58" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M89 570 Q114 456 176 429 L207 600 H92Z M391 570 Q366 456 304 429 L273 600 H388Z" fill="{background}" opacity=".32"/>
</svg>'''
	return portrait.encode("utf-8")


def build_demo_profiles() -> list[dict[str, object]]:
	profiles = []
	for index, (name, profession, short_bio, biography, dream) in enumerate(PROFILES):
		profiles.append({
			"slug": f"demo-person-{index + 1:02d}",
			"name": name,
			"profession": profession,
			"short_bio": short_bio,
			"biography": (
				biography
				if "gerçek" in biography.lower()
				else f"{biography} Bu anlatı tamamen kurgusaldır; gerçek bir kişiyi veya tutukluluk durumunu temsil etmez."
			),
			"status": "temsili",
			"dreams": dream,
			"image_url": None,
			"image_data": build_portrait_svg(index),
			"image_media_type": "image/svg+xml",
			"is_demo": True,
			"is_published": True,
		})
	return profiles